   118	/** Pure mapper for deterministic tests; no user content reaches a child span. */
   119	export function mapAgentTraceToSpans(envelope: AgentTraceEnvelope, allowContent: boolean): ArizeSpanRecord[] {
   120		const root: ArizeSpanRecord = {
   121			name: "keating.agent.turn", kind: "AGENT", status: envelope.status === "success" ? "success" : "error",
   122			attributes: {
   123				"keating.schema.version": envelope.schema_version, "keating.run.id": envelope.run_id,
   124				"session.id": envelope.session_id, "keating.turn.index": envelope.turn_index,
   125				"keating.eval.eligible": allowContent && Boolean(envelope.evaluation_content), "keating.duration_ms": envelope.duration_ms,
   126				"keating.source": envelope.source, "keating.app.version": envelope.app_version, "keating.surface": envelope.surface,
   127				...(envelope.error_category ? { "keating.error.category": envelope.error_category } : {}),
   128				...(allowContent && envelope.evaluation_content ? { "input.value": envelope.evaluation_content.input, "output.value": envelope.evaluation_content.output } : {}),
   129			},
