   151	/**
   152	 * Best-effort OTLP export. The tracer provider is deliberately short-lived so
   153	 * a serverless request cannot leak global instrumentation into another route.
   154	 */
   155	export async function exportAgentTrace(envelope: AgentTraceEnvelope, config = readServerArizeConfig()): Promise<void> {
   156		const records = mapAgentTraceToSpans(envelope, config.evaluationContentEnabled);
   157		if (testTraceExporter) {
   158			await testTraceExporter(records);
   159			return;
   160		}
   161		if (!config.enabled || !config.apiKey || !config.spaceId || !config.endpoint || !config.projectName) return;
   162		const exporter = new OTLPTraceExporter({ url: config.endpoint, headers: { "arize-space-id": config.spaceId, "arize-api-key": config.apiKey } });
   163		const provider = new NodeTracerProvider({
   164			resource: resourceFromAttributes({ "openinference.project.name": config.projectName }),
   165			spanProcessors: [new SimpleSpanProcessor(exporter)],
   166		});
   167		const tracer = provider.getTracer("keating.arize.relay");
   168		const root = tracer.startSpan(records[0].name);
   169		root.setAttributes({ "openinference.span.kind": "AGENT", ...records[0].attributes });
   170		const rootContext = trace.setSpan(context.active(), root);
   171		for (const record of records.slice(1)) {
   172			const child = tracer.startSpan(record.name, undefined, rootContext);
   173			child.setAttributes({ "openinference.span.kind": record.kind, ...record.attributes });
   174			if (record.status === "error") child.setStatus({ code: SpanStatusCode.ERROR });
   175			child.end();
   176		}
   177		if (records[0].status === "error") root.setStatus({ code: SpanStatusCode.ERROR });
   178		root.end();
   179		await provider.forceFlush();
   180		await provider.shutdown();
   181	}
