   185		if (!config.evaluationContentEnabled) return { ...parsed, evaluation_content: undefined };
   186		const cap = config.maxContentChars;
   187		if (parsed.evaluation_content && (parsed.evaluation_content.input.length > cap || parsed.evaluation_content.output.length > cap)) throw new Error("content exceeds configured limit");
