   191	export function requestWithinLimit(contentLength: string | undefined): boolean {
   192		if (!contentLength) return true;
   193		const parsed = Number(contentLength);
   194		return Number.isInteger(parsed) && parsed >= 0 && parsed <= MAX_BODY_BYTES;
   195	}
