     1	import { createError, defineEventHandler, getHeader, getRequestIP, getRequestURL, readRawBody, setResponseStatus } from "h3";
     2	import { exportAgentTrace, IpRateLimiter, readServerArizeConfig, requestWithinLimit, validateTracePayload } from "../../../../utils/arize-observability";
     3	
     4	const rateLimiter = new IpRateLimiter();
     5	
     6	export default defineEventHandler(async (event) => {
     7		if (event.method !== "POST") throw createError({ statusCode: 405, statusMessage: "Use POST for Arize traces." });
     8		const config = readServerArizeConfig();
     9		if (!config.enabled) { setResponseStatus(event, 204); return null; }
    10		const contentType = getHeader(event, "content-type") ?? "";
    11		if (!contentType.toLowerCase().startsWith("application/json")) throw createError({ statusCode: 415, statusMessage: "JSON required." });
    12		if (!requestWithinLimit(getHeader(event, "content-length"))) throw createError({ statusCode: 413, statusMessage: "Trace is too large." });
    13		const origin = getHeader(event, "origin");
    14		const url = getRequestURL(event);
    15		if (!origin || origin !== url.origin) throw createError({ statusCode: 403, statusMessage: "Same-origin request required." });
    16		if (!rateLimiter.allow(getRequestIP(event, { xForwardedFor: true }) ?? "unknown", config.rateLimitPerMinute)) throw createError({ statusCode: 429, statusMessage: "Try again later." });
    17		let payload: unknown;
    18		try {
    19			const rawBody = await readRawBody(event, false);
    20			if (rawBody === undefined || Buffer.byteLength(rawBody, "utf8") > 64 * 1024) {
    21				throw createError({ statusCode: 413, statusMessage: "Trace is too large." });
    22			}
    23			payload = JSON.parse(rawBody);
    24		} catch (error) {
    25			if (error && typeof error === "object" && "statusCode" in error) throw error;
    26			throw createError({ statusCode: 400, statusMessage: "Invalid JSON." });
    27		}
    28		let envelope;
    29		try { envelope = validateTracePayload(payload, config); } catch { throw createError({ statusCode: 400, statusMessage: "Invalid trace envelope." }); }
    30		void exportAgentTrace(envelope, config);
    31		setResponseStatus(event, 202);
    32		return { accepted: true };
    33	});

