}; limits q/a/expl/rubric/option ${quiz.review.maxQuestionChars}/${quiz.review.maxAnswerChars}/${quiz.review.maxExplanationChars}/${quiz.review.maxRubricChars}/${quiz.review.maxOptionChars} chars`,\n\t\t``,\n\t];\n\tfor (const q of quiz.questions) {\n\t\tlines.push(`## ${q.id} — ${q.level} (${q.type})`);\n\t\tlines.push(q.question);\n\t\tif (q.options) {\n\t\t\tlines.push(\"\");\n\t\t\tfor (let i = 0; i < q.options.length; i++) {\n\t\t\t\tlines.push(`${String.fromCharCode(65 + i)}. ${q.options[i]}`);\n\t\t\t}\n\t\t}\n\t\tlines.push(\"\");\n\t\tif (q.rubric) lines.push(`*Rubric:* ${q.rubric}`);\n\t\tlines.push(\"\");\n\t}\n\treturn lines.join(\"\\n\") + \"\\n\";\n}\n\nexport function quizAnswerKeyToMarkdown(quiz: Quiz): string {\n\tconst lines = [\n\t\t`# Answer Key: ${quiz.topic}`,\n\t\t\"\",\n\t];\n\tfor (const q of quiz.questions) {\n\t\tlines.push(`## ${q.id}`);\n\t\tlines.push(`**Answer:** ${q.correctAnswer}`);\n\t\tlines.push(`**Explanation:** ${q.explanation}`);\n\t\tlines.push(\"\");\n\t}\n\treturn lines.join(\"\\n\") + \"\\n\";\n}\n",
