   197	export class IpRateLimiter {
   198		private readonly records = new Map<string, number[]>();
   199		allow(key: string, limit: number, now = Date.now()): boolean {
   200			const cutoff = now - 60_000;
   201			const current = (this.records.get(key) ?? []).filter((time) => time > cutoff);
   202			if (current.length >= limit) { this.records.set(key, current); return false; }
   203			current.push(now); this.records.set(key, current); return true;
   204		}
