    35	export class ArizeTraceClient {
    36		private failed: AgentTraceEnvelopeV1 | undefined;
    37	
    38		constructor(
    39			private readonly fetcher: typeof fetch = fetch,
    40			private readonly onStatus: (status: ArizeTraceStatus) => void = () => undefined,
    41			private readonly onTurnOff: () => void = () => undefined,
    42		) {}
    43	
    44		turnOff(): void {
    45			this.failed = undefined;
    46			this.onTurnOff();
    47		}
    48	
    49		async submit(envelope: AgentTraceEnvelopeV1, config: ArizePublicConfig, preferenceEnabled: boolean): Promise<void> {
    50			if (!config.enabled || !preferenceEnabled) {
    51				this.onStatus({ state: "disabled" });
    52				return;
    53			}
    54			const payload = !config.evaluationContentEnabled
    55				? { ...envelope, evaluation_content: undefined }
    56				: envelope.evaluation_content
    57					? {
    58						...envelope,
    59						evaluation_content: {
    60							input: envelope.evaluation_content.input.slice(0, config.maxContentChars),
    61							output: envelope.evaluation_content.output.slice(0, config.maxContentChars),
    62						},
    63					}
    64					: envelope;
    65			try {
    66				const response = await this.fetcher(TRACE_PATH, {
    67					method: "POST",
    68					credentials: "same-origin",
    69					headers: { "content-type": "application/json" },
    70					body: JSON.stringify(payload),
    71				});
    72				if (!response.ok) throw new Error(`status_${response.status}`);
    73				this.failed = undefined;
    74				this.onStatus({ state: "sent" });
    75			} catch {
    76				this.failed = payload;
    77				this.onStatus({
    78					state: "failed",
    79					retry: async () => {
    80						if (this.failed) await this.submit(this.failed, config, preferenceEnabled);
    81					},
    82					turnOff: () => {
    83						this.turnOff();
    84					},
    85				});
    86			}
    87		}
    88	}

