    28	    );
    29	  }
    30	  const selectedRuntime = runtime.selected;
    31	
    32	  const args = ["-p", "--no-session", "--no-tools", "--no-extensions", "--no-skills"];
    33	
    34	  if (options.systemPrompt) {
    35	    args.push("--system-prompt", options.systemPrompt);
    36	  }
    37	
    38	  if (options.json) {
    39	    args.push("--mode", "json");
    40	  }
    41	
    42	  if (options.thinking) {
    43	    args.push("--thinking", options.thinking);
    44	  }
    45	
    46	  const finalArgs = mergePiDefaults(config, [...args, prompt]);
    47	
    48	  try {
    49	    const response = await withApiRetry(() => {
    50	    let result;
    51	    try {
    52	      const isBinary = selectedRuntime.kind === "binary";
    53	      const command = selectedRuntime.command;
    54	      const spawnArgs = isBinary ? finalArgs : [selectedRuntime.cliPath!, ...finalArgs];
    55	
    56	      result = spawnSync(command, spawnArgs, {
    57	        cwd,
    58	        stdio: "pipe",
    59	        encoding: "utf8",
    60	        env: {
    61	          ...process.env,
    62	          PI_SKIP_VERSION_CHECK: "1",
