   110	/**
   111	 * Specialized helper for JSON completions.
   112	 */
   113	export async function piCompleteJson<T>(cwd: string, prompt: string, options: PiCompletionOptions = {}): Promise<T> {
   114	  const response = await piComplete(cwd, prompt, { ...options, json: true });
   115	  try {
   116	    // Some models output reasoning BEFORE the JSON block.
   117	    // We try to find all JSON-like blocks and pick the one that parses successfully,
   118	    // prioritizing the last one.
   119	    const matches = response.match(/\{[\s\S]*?\}/g);
   120	    if (!matches) return JSON.parse(response) as T;
   121	    
   122	    for (let i = matches.length - 1; i >= 0; i--) {
   123	      try {
   124	        return JSON.parse(matches[i]) as T;
   125	      } catch {
   126	        continue;
   127	      }
   128	    }
   129	    throw new Error("No valid JSON block found in response.");
   130	  } catch (error) {
   131	    throw new Error(`Failed to parse agent JSON response: ${response}\nError: ${error}`);
   132	  }
   133	}

